// Checks that the order warranty of LinkedHashMap objects are preserved
// when pushing them in a MapContext.
@Test
public void ControllerConfigLikeContext() {
    Map<String, String> propsA = UtilMisc.toMap(LinkedHashMap::new, "aa", "1", "ab", "1");
    Map<String, String> propsB = UtilMisc.toMap(LinkedHashMap::new, "ba", "3", "bb", "8", "bc", "1", "bd", "14");
    PNode pn = new PNode(propsA, new PNode(propsB, new PNode(), new PNode()), new PNode(new PNode()), new PNode());
    MapContext<String, String> mc = pn.allProps();
    assertThat("insertion order of LinkedHashMap is preserved by the 'values' method", mc.values(), contains("1", "1", "3", "8", "1", "14"));
}

